catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
	if (isLoading || newValue == '') {
		return;
	}
	g_form.setDisplay('field_1', false);
	g_form.setDisplay('field_2', false);
	g_form.setDisplay('field_3', false);
	g_form.setDisplay('field_4', false);
	g_form.setDisplay('field_5', false);
	g_form.setDisplay('field_6', false);
	g_form.setDisplay('field_7', false);
	g_form.setDisplay('field_8', false);
	g_form.setDisplay('field_9', false);
	g_form.setDisplay('field_10', false);
	//alert('**********the newValue is    ' + newValue);
	if (newValue == 1) {
		g_form.setDisplay('field_1', true);
		g_form.setDisplay('field_2', true);
	}
	if (newValue == 2) {
		g_form.setDisplay('field_3', true);
		g_form.setDisplay('field_4', true);
	}
	else if (newValue == 3) {
		g_form.setDisplay('field_5', true);
		g_form.setDisplay('field_6', true);
	}
	else if (newValue == 4) {
		g_form.setDisplay('field_7', true);
	}
	else if (newValue == 5) {
		g_form.setDisplay('field_8', true);
	}
	else if (newValue == 6) {
		g_form.setDisplay('field_9', true);
		g_form.setDisplay('field_10', true);
	}
}
